    display.drawLine(0, 0, 21, 17, WHITE);
    display.drawLine(128,64, 116,54, WHITE);
    display.display();
    delay(300);

    display.drawLine(21, 17, 34, 18, WHITE);
    display.drawLine(116,54, 106, 44, WHITE);
    display.display();
